const rpc=async(p,type,fields={})=>{const r=await p.evaluate(x=>chrome.runtime.sendMessage(x),{type,...fields});assert.equal(r.ok,true,JSON.stringify(r));return r.data;};
const op=()=>crypto.randomUUID();
async function ready(h){const p=h.archive;await p.locator('#enable-consent').click();await eventually(async()=>(await rpc(p,'GET_STATUS')).consented);if(await p.locator('#onboarding-skip').isVisible())await p.locator('#onboarding-skip').click();await rpc(p,'UPDATE_PREFERENCES',{changes:{language:'zh-CN'}});return p;}
const offline=h=>{assert.equal(h.externalRequests,0);assert.equal(h.extensionNetworkRequests,0);assert.equal(h.deepSeekRequests.length,0);assert.deepEqual(h.errors,[]);};
async function shot(p,name){await mkdir('work/ux-r3',{recursive:true});await p.screenshot({path:`work/ux-r3/${name}.png`});}
const nav=thoughtPrimary;
for(const variant of ['source','release'])test(`UX-R3 removed mid-topic reading anchor opens the nearby Thought with an explicit location notice (${variant})`,{timeout:90000},async()=>{
 const release=variant==='release'?await mkdtemp(join(tmpdir(),'paia-nearby-anchor-')):null;
 if(release)execFileSync('python3',['scripts/build_current_release.py',release],{stdio:'pipe'});
 const h=await FakeChatGPT.start({onboarding:true,...(release?{extensionPath:release}:{})});try{const p=await ready(h),topic=await rpc(p,'CREATE_LIBRARY_TOPIC',{topic:{name:'Synthetic nearby position',operationId:op()}});for(let i=0;i<7;i++)await rpc(p,'CONTINUE_THINKING',{thought:{operationId:op(),body:'Synthetic readable neighbor '+i,topicId:topic.id}});
  const page=await rpc(p,'TOPIC_DOCUMENT_PAGE',{options:{topicId:topic.id,sort:'asc'}}),middle=page.items[3].entry,next=page.items[4].entry;await rpc(p,'THOUGHT_POSITION',{position:{topicId:topic.id,entryId:middle.id,revision:middle.revision,offset:6,sort:'asc',expanded:[]}});const paths=await rpc(p,'GET_LIBRARY_PATHS',{id:middle.id}),current=await rpc(p,'GET_LIBRARY_TOPIC',{id:topic.id});await rpc(p,'PLACE_LIBRARY_ENTRY',{placement:{entryId:middle.id,topicId:topic.id,expectedEntryRevision:middle.revision,expectedTopicRevision:current.organizationRevision,expectedPlacementRevision:paths[0].placement.revision,remove:true,operationId:op()}});
  const resolvedBeforeOpen=await rpc(p,'THOUGHT_POSITION',{position:{topicId:topic.id}});assert.equal(resolvedBeforeOpen.entryId,next.id,'nearest persisted anchor is the next surviving Thought');
  await nav(p,'thoughts');await p.locator(`.personal-topic-link[data-topic-id="${topic.id}"]`).click();await p.getByText('原位置已移除，从附近继续。',{exact:true}).waitFor();const diagnostic=await p.evaluate(async expected=>{
   const sample=stage=>({stage,scrollY,maxScroll:document.documentElement.scrollHeight-innerHeight,viewport:innerHeight,clientHeight:document.documentElement.clientHeight,scrollBehavior:getComputedStyle(document.documentElement).scrollBehavior,fonts:document.fonts.status,rows:[...document.querySelectorAll('#topic-body [data-entry-id]')].map(el=>{const r=el.getBoundingClientRect(),body=el.querySelector('[data-entry-field="body"]'),b=body?.getBoundingClientRect();let rangeTop=null;if(el.dataset.entryId===expected.id&&body){const walker=document.createTreeWalker(body,NodeFilter.SHOW_TEXT);let node,offset=expected.offset;while(node=walker.nextNode()){if(offset<=node.length){const range=document.createRange();range.setStart(node,offset);range.collapse(true);rangeTop=range.getBoundingClientRect().top;break;}offset-=node.length;}}return {id:el.dataset.entryId,top:r.top,bottom:r.bottom,bodyTop:b?.top,bodyBottom:b?.bottom,rangeTop};})});
   const initial=sample('initial'),firstVisible=initial.rows.find(row=>row.bottom>140&&row.top<innerHeight)?.id||null;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const frame=sample('two-animation-frames');await document.fonts.ready;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return {expected,firstVisible,samples:[initial,frame,sample('fonts-ready-two-frames')]};
  },{id:next.id,offset:resolvedBeforeOpen.offset});const resolved=await rpc(p,'THOUGHT_POSITION',{position:{topicId:topic.id}});console.log('REMOVED_ANCHOR_DIAGNOSTIC '+JSON.stringify({...diagnostic,resolvedBeforeOpen,resolved}));await mkdir('work/ux-r3',{recursive:true});await writeFile(`work/ux-r3/removed-anchor-diagnostic-${variant}.json`,JSON.stringify({...diagnostic,resolvedBeforeOpen,resolved},null,2));await shot(p,'removed-topic-anchor-diagnostic-'+variant);
  // Continuous prefetch can reveal a predecessor card above the correct text
  // anchor. Check exact identity and physically feasible text alignment instead.
  assert.equal(resolved.entryId,next.id,'persisted nearest target survives prefetch');
  for(const settled of diagnostic.samples){const target=settled.rows.find(row=>row.id===next.id);
  assert.ok(target&&Number.isFinite(target.rangeTop),'resolved next Thought has a measurable text anchor');
  assert.ok(target.rangeTop>=139&&target.rangeTop<settled.viewport,'next Thought text anchor is inside the readable viewport');
  assert.ok(Math.abs(target.rangeTop-140)<=1||(Math.abs(settled.scrollY-settled.maxScroll)<=1&&target.rangeTop>140),'text aligns at140 unless the exact remaining scroll range cannot reach it');}assert.equal(await p.locator(`#topic-body [data-entry-id="${middle.id}"]`).count(),0);assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id:middle.id})).body,middle.body);await shot(p,'removed-topic-anchor-'+variant);offline(h);
 }finally{await h.close();if(release)await rm(release,{recursive:true,force:true});}
});
test('UX-R3 real Reader → add whole Input → two Topics → independent edit → restore; headless responsive matrix',{timeout:180000},async()=>{const h=await FakeChatGPT.start({onboarding:true});try{const p=await ready(h);await p.setViewportSize({width:1440,height:900});const text='UXR3_ARCHIVE 原始文字，保留过去的事实。\n中文 👩🏽‍💻 é 与换行。';await h.open({id:'uxr3-source',title:'合成旧记录',base:1609459200,messages:[{id:'uxr3-msg',text}]});await eventually(async()=>(await h.state()).records.length===1);await p.bringToFront();await p.locator('.archive-navigator-group-toggle').filter({hasText:'未归属 Project'}).waitFor();await openArchiveWindow(p,{label:'UX-R3 Archive window is reachable'});const field=p.locator('.library-prose').first();await field.waitFor();const inputId=await field.getAttribute('data-edit-id');await field.click({button:'right'});await p.locator('#context-menu button').filter({hasText:'加入主题'}).click();const dialog=p.locator('#topic-action-dialog');await dialog.getByRole('button',{name:'新建主题',exact:true}).click();await dialog.getByLabel('新主题名称').fill('主题 A');await dialog.getByRole('button',{name:'创建主题',exact:true}).click();await dialog.getByLabel('主题 A',{exact:true}).waitFor();for(const appearance of ['light','dark']){await rpc(p,'UPDATE_PREFERENCES',{changes:{appearance}});for(const [width,height]of [[1440,900],[1024,768],[390,844],[320,720]]){await p.setViewportSize({width,height});await shot(p,`picker-${appearance}-${width}`);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}}await p.setViewportSize({width:1440,height:900});await dialog.getByRole('button',{name:'加入',exact:true}).click();await eventually(()=>dialog.isVisible().then(x=>!x));assert.equal((await rpc(p,'GET_INPUT',{id:inputId})).libraryText,null);await nav(p,'thoughts');await p.locator('.personal-topic-link[data-topic-id]').filter({hasText:'主题 A'}).click();const thought=p.locator('#topic-body [data-entry-field="body"]').first();await thought.waitFor();const id=await thought.evaluate(el=>el.closest('[data-entry-id]').dataset.entryId);await thought.fill('UXR3_MANUAL 今天人工改写的思想');await eventually(async()=>(await rpc(p,'GET_LIBRARY_ENTRY',{id})).body==='UXR3_MANUAL 今天人工改写的思想');assert.equal((await rpc(p,'GET_INPUT',{id:inputId})).libraryText,null);await thoughtHistoryAction(p,'library-undo');await eventually(async()=>(await rpc(p,'GET_LIBRARY_ENTRY',{id})).body===text);assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id})).bodyBinding,'input');await thoughtHistoryAction(p,'library-redo');await eventually(async()=>(await rpc(p,'GET_LIBRARY_ENTRY',{id})).body==='UXR3_MANUAL 今天人工改写的思想');
 const second=await rpc(p,'CREATE_LIBRARY_TOPIC',{topic:{name:'主题 B',operationId:op()}});const row=await rpc(p,'GET_LIBRARY_ENTRY',{id});await rpc(p,'ADD_TO_TOPICS',{selection:{id,kind:'thought',expectedRevision:row.revision,operationId:op(),topicIds:[second.id]}});await p.locator('#back').click();await p.locator('.personal-topic-link[data-topic-id]').filter({hasText:'主题 B'}).click();await eventually(()=>thought.textContent().then(x=>x==='UXR3_MANUAL 今天人工改写的思想'));const b=await rpc(p,'GET_INPUT',{id:inputId});await rpc(p,'EDIT_DOCUMENT',{edit:{operationId:op(),documentId:b.documentId,blocks:[{id:b.id,expectedRevision:b.revision,libraryText:'UXR3_UPDATED 档案更新',note:b.note,excluded:false}]}});await eventually(()=>p.locator('.entry-stale').filter({hasText:'档案有更新'}).isVisible());assert.equal(await thought.textContent(),'UXR3_MANUAL 今天人工改写的思想');
 for(const appearance of ['light','dark']){await rpc(p,'UPDATE_PREFERENCES',{changes:{appearance}});for(const [width,height]of [[1440,900],[1024,768],[390,844],[320,720]]){await p.setViewportSize({width,height});await pause(120);await shot(p,`topic-${appearance}-${width}`);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}}
 await p.setViewportSize({width:1440,height:900});const actions=p.locator('#topic-body .library-entry .library-actions').first();await actions.locator('summary').click();await actions.getByRole('button',{name:'查看档案当前文字',exact:true}).click();await dialog.getByRole('button',{name:'恢复为档案当前文字'}).waitFor();for(const appearance of ['light','dark']){await rpc(p,'UPDATE_PREFERENCES',{changes:{appearance}});for(const [width,height]of [[1440,900],[1024,768],[390,844],[320,720]]){await p.setViewportSize({width,height});await shot(p,`compare-${appearance}-${width}`);}}await p.setViewportSize({width:1440,height:900});await shot(p,'compare');p.once('dialog',d=>d.accept());await dialog.getByRole('button',{name:'恢复为档案当前文字'}).click();await eventually(async()=>(await rpc(p,'GET_LIBRARY_ENTRY',{id})).bodyBinding==='input');assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id})).body,'UXR3_UPDATED 档案更新');offline(h);
 }finally{await h.close();}});

