  await body(whole.id).click();assert.equal(await body(whole.id).evaluate(el=>document.activeElement===el),true);await body(whole.id).evaluate(el=>{el.textContent='UXR3 双向的新文字';el.closest('[data-entry-id]').querySelector('[data-entry-field="note"]').value='UXR3 同次编辑的备注';el.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText'}));});await eventually(async()=>(await rpc(p,'GET_INPUT',{id:inputId})).libraryText==='UXR3 双向的新文字');assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id:whole.id})).note,'UXR3 同次编辑的备注');assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id:partial.id})).body,original.slice(0,8));const beforeOptOut=await rpc(p,'GET_INPUT',{id:inputId});await p.locator(`[data-entry-id="${whole.id}"] [data-reverse-edit-disable]`).click();await eventually(async()=>!(await rpc(p,'GET_THOUGHT_REVERSE_EDIT')).enabled);assert.deepEqual(await rpc(p,'GET_INPUT',{id:inputId}),beforeOptOut,'restrictive opt-out itself never writes Input');assert.equal(await p.locator('#library-undo').evaluate(el=>getComputedStyle(el).pointerEvents),'auto');assert.equal(await p.locator('#library-undo').isEnabled(),true);let prompt=p.waitForEvent('dialog');await thoughtHistoryAction(p,'library-undo');await (await prompt).dismiss();assert.equal((await rpc(p,'GET_INPUT',{id:inputId})).libraryText,'UXR3 双向的新文字');assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id:whole.id})).note,'UXR3 同次编辑的备注');prompt=p.waitForEvent('dialog');await thoughtHistoryAction(p,'library-undo');await (await prompt).accept();await eventually(async()=>(await rpc(p,'GET_INPUT',{id:inputId})).libraryText===original);assert.equal((await rpc(p,'GET_LIBRARY_ENTRY',{id:whole.id})).note,'');assert.equal((await rpc(p,'GET_THOUGHT_REVERSE_EDIT')).enabled,false);
