  await p.locator('#thought-root-source').getByRole('button',{name:'接着写',exact:true}).click();const workspace=p.locator('#thought-writing-workspace'),draft=workspace.getByRole('textbox',{name:'今天的新想法'}),body='UXR3_CURRENT 新的未保存表达 👩🏽‍💻\n保留每一行。';await workspace.getByRole('button',{name:'保存想法',exact:true}).click();await workspace.getByText('先写下一点内容。',{exact:true}).waitFor();assert.deepEqual(await p.evaluate(()=>__writeCalls),[]);await draft.fill(body);await draft.evaluate(node=>globalThis.__currentWriteDraft=node);
